import java.util.*;
class ViewReplacementTest{public static void main(String[]args){var old=new TerraForge.World(32,62,1);var next=new TerraForge.World(64,62,2);Arrays.fill(next.height,100);var viewer=new MinecraftPreview();viewer.world=old;viewer.x=500;viewer.z=500;viewer.y=50;viewer.replacement.set(next);viewer.building.set(true);if(viewer.adoptReplacement()||viewer.world!=old)throw new AssertionError("Changed world while old mesh was building");viewer.building.set(false);if(!viewer.adoptReplacement()||viewer.world!=next||viewer.patch!=null||viewer.x>=64||viewer.z>=64||viewer.y<102)throw new AssertionError("Preview retained stale map or camera");MinecraftPreview.active=viewer;MinecraftPreview.replaceWorld(old);if(viewer.replacement.get()!=old)throw new AssertionError("Editor replacement did not reach preview");MinecraftPreview.active=null;viewer.worker.shutdownNow();int n=4096;var w=new TerraForge.World(n,62,3);Arrays.fill(w.height,90);w.environment.water=EnvironmentMap.filled(n*n,62);w.environment.river=new float[n*n];for(int z=0;z<n;z++){int i=z*n+9;w.environment.water[i]=90;w.height[i]=87;w.environment.river[i]=1;}var image=EnvironmentView.render(w,1);if(image.getRGB(4,400)==image.getRGB(5,400))throw new AssertionError("2D overview omitted stream between sample columns");System.out.println("PASS: preview adopts replacement only after worker completes, discards old mesh, clamps camera; 2D overview retains narrow off-grid streams");}}
